const commandPattern = /^\/([A-Za-z0-9_]+)(?:@[A-Za-z0-9_]+)?(?:\s+([\s\S]*))?$/i;
const text = (value) => (value == null ? '' : String(value));

function sourceParts(update) {
  const callback = update?.callback_query;
  const message = update?.message ?? update?.edited_message ?? callback?.message;
  const actor = callback?.from ?? message?.from;
  return { callback, message, actor };
}

function parseCommand(rawText) {
  const raw = text(rawText).trim();
  const match = commandPattern.exec(raw);
  if (!match) return { command: '', args: [], intent: 'COMMAND_NOT_AVAILABLE', raw_text: raw };
  const command = `/${match[1].toLowerCase()}`;
  const args = text(match[2]).trim() ? text(match[2]).trim().split(/\s+/).slice(0, 20) : [];
  const intent = command === '/trangthai' ? 'READ_STATUS' : command === '/help' ? 'READ_HELP' : command === '/retry' ? 'MANUAL_RETRY' : 'ROUTE_COMMAND';
  return { command, args, intent, raw_text: raw };
}

function normalizeTelegramUpdate(update) {
  const updateId = update?.update_id;
  const { callback, message, actor } = sourceParts(update);
  if (updateId == null || !message?.chat?.id || !actor?.id) {
    throw new Error('Telegram update requires update_id, message.chat.id and message.from.id');
  }
  const parsed = parseCommand(callback?.data ?? message.text);
  const intent = callback && parsed.intent === 'COMMAND_NOT_AVAILABLE' ? 'ROUTE_COMMAND' : parsed.intent;
  const stableId = text(updateId);
  const replyTarget = {
    chat_id: text(message.chat.id),
    message_thread_id: message.message_thread_id == null ? null : text(message.message_thread_id),
  };
  const idempotencyKey = callback?.id ? `tg-callback-${text(callback.id)}` : `tg-${stableId}`;
  const operationId = callback?.id ? idempotencyKey : `tg-${stableId}`;
  return {
    envelope: {
      request_id: `tg-${stableId}`,
      operation_id: operationId,
      event_type: 'TELEGRAM_UPDATE',
      actor_user_id: text(actor.id),
      branch_id: null,
      business_date: null,
      config_version: null,
      payload: {
        command: parsed.command,
        intent,
        args: parsed.args,
        raw_text: parsed.raw_text,
        callback_id: callback?.id ? text(callback.id) : null,
        callback_data: callback?.data ? text(callback.data) : null,
        idempotency_key: idempotencyKey,
      },
    },
    reply_target: replyTarget,
    command: parsed.command,
    args: parsed.args,
    callback: callback ? { id: text(callback.id), data: text(callback.data) } : null,
  };
}

function normalizeStatusUpdate(update) {
  const normalized = normalizeTelegramUpdate(update);
  const isStatus = normalized.command === '/trangthai';
  return {
    ...normalized,
    envelope: {
      ...normalized.envelope,
      payload: {
        ...normalized.envelope.payload,
        intent: isStatus ? 'READ_STATUS' : 'COMMAND_NOT_AVAILABLE',
      },
    },
    command: isStatus ? '/trangthai' : normalized.command,
  };
}

const FULL_ROUTER_SHEETS = Object.freeze([
  'CONFIG_ROLE',
  'CONFIG_PERMISSION',
  'CONFIG_USER_ROLE',
  'CONFIG_ROLE_PERMISSION',
  'CONFIG_TOPIC',
  'CONFIG_LENH',
  'EVENT_LOG',
]);
const HELP_ROUTER_SHEETS = Object.freeze([
  'CONFIG_ROLE',
  'CONFIG_PERMISSION',
  'CONFIG_USER_ROLE',
  'CONFIG_ROLE_PERMISSION',
  'CONFIG_TOPIC',
  'CONFIG_LENH',
]);

/**
 * Return only the configuration tabs needed by a Telegram command.
 * Core sheets are always read by WF01; this list controls the optional router
 * reads so read-only help does not wait on operational/audit tabs.
 */
function requiredSheetNames(command) {
  const normalized = command == null ? '' : String(command).trim().toLowerCase();
  if (normalized === '/trangthai') return [];
  if (normalized === '/help') return [...HELP_ROUTER_SHEETS];
  if (normalized === '/retry') return [...FULL_ROUTER_SHEETS, 'RETRY_CONTEXT'];
  return [...FULL_ROUTER_SHEETS];
}


const update = $input.first()?.json ?? {};
const normalized = normalizeTelegramUpdate(update);
normalized.envelope.payload.required_sheet_names = requiredSheetNames(normalized.command);
return [{ json: normalized }];

const effectiveWindowText = (value) => (value == null ? '' : String(value).trim());

function isWithinEffectiveWindow(row, now) {
  const current = Date.parse(now);
  const from = effectiveWindowText(row?.effective_from);
  const to = effectiveWindowText(row?.effective_to);
  if (from && Number.isNaN(Date.parse(from))) return false;
  if (to && Number.isNaN(Date.parse(to))) return false;
  if ((from || to) && Number.isNaN(current)) return false;
  return (!from || current >= Date.parse(from))
    && (!to || current <= Date.parse(to));
}

const targets = [
  {
    workflow_name: 'WF05_V2_MO_PHIEN_KIEM_KE',
    node_name: 'Call Worker WF05_V2_MO_PHIEN_KIEM_KE',
    config_names: ['WF05_V2_MO_PHIEN_KIEM_KE'],
  },
  {
    workflow_name: 'WF06_V2_NHAN_SO_DEM',
    node_name: 'Call Worker WF06_V2_NHAN_SO_DEM',
    config_names: ['WF06_V2_NHAN_SO_DEM'],
  },
  {
    workflow_name: 'WF08_V2_HOA_DON_NHAP',
    node_name: 'Call Worker WF08_V2_HOA_DON_NHAP',
    config_names: ['WF08_V2_HOA_DON_NHAP', 'WF08_V2_PURCHASE_INGESTION'],
  },
  {
    workflow_name: 'WF09_V2_BAO_CAO_BAN',
    node_name: 'Call Worker WF09_V2_BAO_CAO_BAN',
    config_names: ['WF09_V2_BAO_CAO_BAN', 'WF09_V2_SALES_INGESTION'],
  },
];

function resolveWorkerTarget(value) {
  const name = value == null ? '' : String(value).trim();
  return targets.find((target) => target.config_names.includes(name) || target.workflow_name === name) ?? null;
}

function availableWorkerTargets() {
  return targets.map((target) => ({ ...target, config_names: [...target.config_names] }));
}


const asText = (value) => (value == null ? '' : String(value).trim());
const active = (row) => asText(row?.trang_thai).toUpperCase() === 'ACTIVE';

const denied = () => ({ allowed: false, denial_code: 'USER_NOT_AUTHORIZED', permission_code: null, branch_id: null, global_scope: false, role_codes: [] });

function authorizeCommand({ actorUserId, command, topic = null, tables, now = new Date().toISOString() } = {}) {
  const userId = asText(actorUserId);
  const user = (tables?.CONFIG_USER ?? []).find((row) => asText(row.user_id) === userId);
  if (!user || !active(user)) return denied();
  const commandText = asText(command).toLowerCase();
  if (commandText === '/trangthai') {
    return { allowed: true, denial_code: null, permission_code: null, branch_id: asText(user.branch_id) || null, global_scope: false, role_codes: [] };
  }
  const commandRow = (tables?.CONFIG_LENH ?? []).find((row) => active(row) && asText(row.command_text).toLowerCase() === commandText);
  if (!commandRow) return denied();
  const permissionCode = asText(commandRow.permission_code);
  if (!permissionCode) {
    if (!['/help', '/trangthai'].includes(commandText)) return denied();
    return { allowed: true, denial_code: null, permission_code: null, branch_id: asText(topic?.branch_id) || asText(user.branch_id) || null, global_scope: false, role_codes: [] };
  }
  if (!topic || !active(topic)) return denied();
  const topicBranch = asText(topic.branch_id);
  const permissions = new Set((tables?.CONFIG_PERMISSION ?? []).filter(active).map((row) => asText(row.permission_code)));
  if (!permissions.has(permissionCode)) return denied();
  const roles = new Set((tables?.CONFIG_ROLE ?? []).filter(active).map((row) => asText(row.role_code)));
  const rolePermissions = (tables?.CONFIG_ROLE_PERMISSION ?? []).filter((row) => active(row) && asText(row.permission_code) === permissionCode);
  const eligible = (tables?.CONFIG_USER_ROLE ?? [])
    .filter((row) => active(row) && asText(row.user_id) === userId && isWithinEffectiveWindow(row, now))
    .filter((row) => (asText(row.branch_id) === '*' || asText(row.branch_id) === topicBranch) && roles.has(asText(row.role_code)))
    .filter((row) => rolePermissions.some((mapping) => asText(mapping.role_code) === asText(row.role_code)));
  if (eligible.length === 0) return denied();
  return {
    allowed: true,
    denial_code: null,
    permission_code: permissionCode,
    branch_id: topicBranch,
    global_scope: eligible.some((row) => asText(row.branch_id) === '*'),
    role_codes: [...new Set(eligible.map((row) => asText(row.role_code)))],
  };
}

function hasPermission({ actorUserId, permissionCode, tables, now, topic = null } = {}) {
  const userId = asText(actorUserId);
  const user = (tables?.CONFIG_USER ?? []).find((row) => asText(row.user_id) === userId);
  if (!user || !active(user)) return false;
  const permissions = new Set((tables?.CONFIG_PERMISSION ?? []).filter(active).map((row) => asText(row.permission_code)));
  if (!permissions.has(asText(permissionCode))) return false;
  const roles = new Set((tables?.CONFIG_ROLE ?? []).filter(active).map((row) => asText(row.role_code)));
  const mapping = (tables?.CONFIG_ROLE_PERMISSION ?? []).filter((row) => active(row) && asText(row.permission_code) === asText(permissionCode));
  return (tables?.CONFIG_USER_ROLE ?? [])
    .filter((row) => active(row) && asText(row.user_id) === userId && isWithinEffectiveWindow(row, now))
    .filter((row) => asText(row.branch_id) === '*' || !topic || asText(row.branch_id) === asText(topic.branch_id))
    .some((row) => roles.has(asText(row.role_code)) && mapping.some((entry) => asText(entry.role_code) === asText(row.role_code)));
}

function hasRole({ actorUserId, roleCode, tables, now, branchId = '*' } = {}) {
  const userId = asText(actorUserId);
  const requestedRole = asText(roleCode);
  const user = (tables?.CONFIG_USER ?? []).find((row) => asText(row.user_id) === userId);
  if (!user || !active(user) || !requestedRole) return false;
  const roles = new Set((tables?.CONFIG_ROLE ?? []).filter(active).map((row) => asText(row.role_code)));
  return roles.has(requestedRole) && (tables?.CONFIG_USER_ROLE ?? []).some((row) => active(row)
    && asText(row.user_id) === userId
    && asText(row.role_code) === requestedRole
    && asText(row.branch_id) === asText(branchId)
    && isWithinEffectiveWindow(row, now));
}

const reservationText = (value) => (value == null ? '' : String(value).trim());

function buildDispatchReservation(envelope, now = new Date().toISOString()) {
  const requestId = reservationText(envelope?.request_id);
  const operationId = reservationText(envelope?.operation_id);
  const sourceKey = reservationText(envelope?.payload?.idempotency_key) || requestId || operationId;
  return {
    sheet: 'OPERATION',
    action: 'APPEND',
    row: {
      operation_id: `router-${operationId}`,
      request_id: requestId,
      operation_type: 'ROUTER_DISPATCH',
      idempotency_key: `router-${sourceKey}`,
      expected_row_count: '1',
      actual_row_count: '',
      checksum: '',
      status: 'PREPARED',
      error_id: '',
      created_at: now,
      updated_at: now,
    },
  };
}


const retryText = (value) => (value == null ? '' : String(value).trim());
const retryFailure = (errorCode, errorId) => ({ ok: false, response: { status: 'ERROR', error_code: errorCode, error_id: errorId }, write_plan: [] });

function planRetry({ actorUserId, errorId, permissionCode, topic = null, tables, now = new Date().toISOString() } = {}) {
  const id = retryText(errorId);
  const row = (tables?.ERROR_BIA ?? []).find((candidate) => retryText(candidate.error_id) === id && retryText(candidate.status).toUpperCase() !== 'RESOLVED');
  const authorizationTopic = topic ?? { branch_id: '*', trang_thai: 'ACTIVE' };
  const authorization = authorizeCommand({ actorUserId, command: '/retry', topic: authorizationTopic, tables, now });
  if (!retryText(permissionCode) || !authorization.allowed || authorization.permission_code !== retryText(permissionCode)) return retryFailure('USER_NOT_AUTHORIZED', `err-${id || 'unknown'}-retry-denied`);
  if (!row) return retryFailure('ERROR_NOT_FOUND', `err-${id || 'unknown'}-not-found`);
  if (!['YES', 'TRUE', '1'].includes(retryText(row.retryable).toUpperCase())) return retryFailure('ERROR_NOT_RETRYABLE', id);
  const operationId = retryText(row.operation_id);
  const originalOperation = (tables?.OPERATION ?? []).find((candidate) => retryText(candidate.operation_id) === operationId);
  const idempotencyKey = retryText(row.idempotency_key) || retryText(originalOperation?.idempotency_key);
  const requestId = retryText(row.request_id) || retryText(originalOperation?.request_id);
  const branchId = retryText(row.branch_id);
  const branchScopeMismatch = !authorization.global_scope && branchId !== authorization.branch_id;
  if (!branchId) return retryFailure('ERROR_BRANCH_MISSING', id);
  if (branchScopeMismatch) return retryFailure('USER_NOT_AUTHORIZED', `err-${id}-retry-branch-denied`);
  if (!idempotencyKey) return retryFailure('ERROR_IDEMPOTENCY_MISSING', id);
  if (!operationId || !requestId) return retryFailure('ERROR_RETRY_CONTEXT_MISSING', id);
  // ERROR_BIA and OPERATION persist identifiers and retryability, not the
  // original request payload. Reconstructing an empty command here could
  // replay a different business action, so retry must fail closed.
  return retryFailure('ERROR_RETRY_CONTEXT_MISSING', id);
}


const routerText = (value) => (value == null ? '' : String(value).trim());
const routerActive = (row) => routerText(row?.trang_thai).toUpperCase() === 'ACTIVE';

function routerMessages(gatewayResult, context) {
  const map = new Map(Object.entries(gatewayResult?.response?.messages ?? {}));
  for (const row of context?.CONFIG_THONG_BAO ?? []) {
    if (routerActive(row)) map.set(routerText(row.message_key), routerText(row.message_text));
  }
  return map;
}

function routerRender(template, values) {
  return routerText(template).replace(/\{([a-z0-9_]+)\}/gi, (_match, key) => routerText(values[key]));
}

function routerErrorText(gatewayResult, context, errorCode, errorId) {
  const map = routerMessages(gatewayResult, context);
  const key = errorCode === 'COMMAND_NOT_AVAILABLE' ? 'COMMAND_NOT_AVAILABLE' : errorCode === 'USER_NOT_ACTIVE' ? 'USER_NOT_ACTIVE' : 'ERROR_GENERIC';
  const response = gatewayResult?.response ?? {};
  const safeErrorId = routerText(errorId || response.error_id) || 'unknown';
  return routerRender(map.get(key) || map.get('ERROR_GENERIC') || 'ERROR error_id={error_id}', { error_id: safeErrorId }).slice(0, 4096);
}

function routerStatusText(gatewayResult, context) {
  const response = gatewayResult?.response ?? {};
  const messages = routerMessages(gatewayResult, context);
  const lines = [
    routerRender(messages.get('STATUS_HEADER'), response),
    routerRender(messages.get('STATUS_GATEWAY_HEALTH_LINE'), response),
    routerRender(messages.get('STATUS_CONFIG_LINE'), response),
    routerRender(messages.get('STATUS_BRANCH_COUNT_LINE'), response),
    ...(response.active_branches ?? []).map((branch) => routerRender(messages.get('STATUS_BRANCH_LINE'), branch)),
    routerRender(messages.get('STATUS_MAINTENANCE_LINE'), response),
  ];
  return lines.filter(Boolean).join('\n').slice(0, 4096);
}

function routerTopicAtReplyTarget(config, replyTarget, activeBranchIds) {
  const matches = (config.CONFIG_TOPIC ?? []).filter((topic) => routerActive(topic)
    && activeBranchIds.has(routerText(topic.branch_id))
    && routerText(topic.chat_id) === routerText(replyTarget?.chat_id)
    && routerText(topic.message_thread_id) === routerText(replyTarget?.message_thread_id));
  return matches.length === 1 ? matches[0] : null;
}

function routerCanViewCommand(row, config, context, actorUserId, now, activeBranchIds, currentTopic) {
  const command = routerText(row.command_text).toLowerCase();
  // The current ERROR_BIA/OPERATION schema cannot replay the source payload.
  // Do not advertise a command that is intentionally fail-closed.
  if (command === '/retry') return false;
  if (!['/help', '/trangthai', '/retry'].includes(command)
    && !resolveWorkerTarget(row.worker_workflow)) return false;
  const permission = routerText(row.permission_code);
  if (!permission) return ['/help', '/trangthai'].includes(routerText(row.command_text).toLowerCase());
  const topicType = routerText(row.topic_type);
  if (!currentTopic || !topicType || routerText(currentTopic.topic_type) !== topicType) return false;
  return routerHasPermission({ actorUserId, permission, branchId: currentTopic.branch_id, config, context, now, activeBranchIds });
}

function routerHelpText(config, context, actorUserId, now, activeBranchIds, replyTarget) {
  const currentTopic = routerTopicAtReplyTarget(config, replyTarget, activeBranchIds);
  const rows = (config.CONFIG_LENH ?? []).filter(routerActive)
    .filter((row) => routerCanViewCommand(row, config, context, actorUserId, now, activeBranchIds, currentTopic))
    .sort((left, right) => Number(routerText(left.ordinal) || 0) - Number(routerText(right.ordinal) || 0));
  const messages = routerMessages({ response: { messages: {} } }, context);
  const lines = [];
  if (messages.get('HELP_HEADER')) lines.push(routerText(messages.get('HELP_HEADER')));
  for (const row of rows) {
    const command = routerText(row.command_text) || routerText(row.command_code);
    const syntax = routerText(row.syntax) || command;
    lines.push(`${command} — ${routerText(row.description_vi)}`);
    lines.push(`  Cú pháp: ${syntax}`);
    lines.push(`  Quyền: ${routerText(row.permission_code) || 'Không yêu cầu'}`);
    lines.push(`  Ví dụ: ${routerText(row.example) || syntax}`);
  }
  return lines.join('\n');
}

function routerAuditPlan(normalized, context, errorCode, topic, now) {
  if (!Array.isArray(context?.EVENT_LOG)) return [];
  const eventKey = routerText(normalized?.envelope?.payload?.idempotency_key) || routerText(normalized?.envelope?.operation_id);
  const eventId = `evt-${eventKey}-${routerText(errorCode).toLowerCase()}`;
  if (context.EVENT_LOG.some((row) => routerText(row.event_id) === eventId)) return [];
  return [{
    sheet: 'EVENT_LOG',
    action: 'APPEND',
    row: {
      event_id: eventId,
      event_type: 'TELEGRAM_ACCESS',
      request_id: routerText(normalized?.envelope?.request_id),
      operation_id: routerText(normalized?.envelope?.operation_id),
      actor_user_id: routerText(normalized?.envelope?.actor_user_id),
      branch_id: routerText(topic?.branch_id),
      topic_type: routerText(topic?.topic_type),
      command: routerText(normalized?.command),
      outcome: 'DENIED',
      error_code: routerText(errorCode),
      created_at: now,
      trang_thai: 'COMMITTED',
    },
  }];
}

function routerHasPermission({ actorUserId, permission, branchId, config, context, now, activeBranchIds }) {
  if (branchId !== '*' && !activeBranchIds.has(routerText(branchId))) return false;
  return hasPermission({
    actorUserId,
    permissionCode: permission,
    tables: { ...config, ...context },
    now,
    topic: { branch_id: branchId },
  });
}

function routerAuthorized({ actorUserId, command, topic, config, context, now }) {
  const authorizationTopic = topic ?? (command === '/retry' ? { branch_id: '*', trang_thai: 'ACTIVE' } : null);
  return authorizeCommand({
    actorUserId,
    command,
    topic: authorizationTopic,
    tables: { ...config, ...context },
    now,
  }).allowed;
}

function decideRouterResponse({ normalized, gatewayResult, now = new Date().toISOString() } = {}) {
  const response = gatewayResult?.response ?? {};
  const config = response.data?.config_tables ?? {};
  const context = response.data?.context_tables ?? {};
  const activeBranchIds = new Set((response.active_branches ?? []).map((branch) => routerText(branch.branch_id)).filter(Boolean));
  const callbackToken = routerText(normalized?.callback?.data);
  const callbackCommand = callbackToken && !routerText(normalized?.command)
    ? (config.CONFIG_LENH ?? []).find((row) => routerActive(row) && [row.command_code, row.command_text].map((value) => routerText(value).toLowerCase()).includes(callbackToken.toLowerCase()))?.command_text
    : null;
  const command = routerText(callbackCommand || normalized?.command).toLowerCase();
  const base = { kind: 'DENY', write_plan: [] };
  if (!gatewayResult?.ok) return { decision: { kind: 'DENY', write_plan: response.error_code === 'USER_NOT_ACTIVE' ? routerAuditPlan(normalized, context, 'USER_NOT_AUTHORIZED', null, now) : [] }, text: routerErrorText(gatewayResult, context, response.error_code, response.error_id) };
  if (command === '/trangthai') return { decision: { kind: 'STATUS', write_plan: [] }, text: routerStatusText(gatewayResult, context) };
  const rawOperationKeys = [normalized?.envelope?.operation_id, normalized?.envelope?.request_id, normalized?.envelope?.payload?.idempotency_key].map(routerText).filter(Boolean);
  const operationKeys = [...rawOperationKeys, ...rawOperationKeys.map((key) => `router-${key}`)];
  const dispatchReservation = buildDispatchReservation(normalized?.envelope, now);
  const routerReservation = (context.OPERATION ?? []).find((row) => routerText(row.operation_id) === routerText(dispatchReservation.row.operation_id)
    && routerText(row.operation_type) === 'ROUTER_DISPATCH');
  const existingOperation = (context.OPERATION ?? []).find((row) => [row.operation_id, row.request_id, row.idempotency_key].map(routerText).some((value) => operationKeys.includes(value)));
  const duplicateGuardOperation = routerReservation ?? existingOperation;
  if (duplicateGuardOperation && routerText(duplicateGuardOperation.status).toUpperCase() !== 'PREPARED') {
    const messages = routerMessages(gatewayResult, context);
    return { decision: { kind: 'DUPLICATE', write_plan: [] }, text: routerText(messages.get('ROUTER_DUPLICATE')) };
  }
  if (command === '/help') return { decision: { kind: 'HELP', write_plan: [] }, text: routerHelpText(config, context, normalized?.envelope?.actor_user_id, now, activeBranchIds, normalized?.reply_target) };
  if (command === '/retry') {
    const errorId = routerText(normalized?.args?.[0]);
    const retryTopic = (config.CONFIG_TOPIC ?? []).find((row) => routerActive(row)
      && activeBranchIds.has(routerText(row.branch_id))
      && routerText(row.chat_id) === routerText(normalized?.reply_target?.chat_id)
      && routerText(row.message_thread_id) === routerText(normalized?.reply_target?.message_thread_id));
    const retryCommand = (config.CONFIG_LENH ?? []).find((row) => routerActive(row) && routerText(row.command_text).toLowerCase() === command);
    const retry = planRetry({
      actorUserId: normalized?.envelope?.actor_user_id,
      errorId,
      permissionCode: retryCommand?.permission_code,
      topic: retryTopic,
      tables: { ...config, ...context },
      now,
    });
    const denied = retry.response.error_code === 'USER_NOT_AUTHORIZED';
    return {
      decision: { ...base, write_plan: denied ? routerAuditPlan(normalized, context, retry.response.error_code, retryTopic, now) : [] },
      text: routerErrorText(gatewayResult, context, retry.response.error_code, retry.response.error_id),
    };
  }
  const commandRow = (config.CONFIG_LENH ?? []).find((row) => routerActive(row) && routerText(row.command_text).toLowerCase() === command);
  if (!commandRow) return { decision: base, text: routerErrorText(gatewayResult, context, 'COMMAND_NOT_AVAILABLE', `err-${routerText(normalized?.envelope?.operation_id)}`) };
  const workerTarget = resolveWorkerTarget(commandRow.worker_workflow);
  if (!workerTarget) return { decision: base, text: routerErrorText(gatewayResult, context, 'COMMAND_NOT_AVAILABLE', `err-${routerText(normalized?.envelope?.operation_id)}-worker-unavailable`) };
  const topic = (config.CONFIG_TOPIC ?? []).find((row) => routerActive(row)
     && activeBranchIds.has(routerText(row.branch_id))
    && routerText(row.chat_id) === routerText(normalized?.reply_target?.chat_id)
    && routerText(row.message_thread_id) === routerText(normalized?.reply_target?.message_thread_id)
    && (!routerText(commandRow.topic_type) || routerText(row.topic_type) === routerText(commandRow.topic_type)));
  if (!routerAuthorized({ actorUserId: normalized?.envelope?.actor_user_id, command, topic, config, context, now, activeBranchIds })) {
    return { decision: { kind: 'DENY', write_plan: routerAuditPlan(normalized, context, 'USER_NOT_AUTHORIZED', topic, now) }, text: routerErrorText(gatewayResult, context, 'USER_NOT_AUTHORIZED', `err-${routerText(normalized?.envelope?.operation_id)}-user_not_authorized`) };
  }
  const messages = routerMessages(gatewayResult, context);
  const idempotencyKey = routerText(normalized?.envelope?.payload?.idempotency_key) || routerText(normalized?.envelope?.request_id);
  const workerEnvelope = {
    ...normalized.envelope,
    event_type: 'TELEGRAM_COMMAND',
    branch_id: routerText(topic?.branch_id),
    config_version: routerText(response.config_version) || normalized.envelope.config_version || null,
    config_snapshot_id: routerText(response.config_snapshot_id) || null,
    payload: {
      ...normalized.envelope.payload,
      command,
      command_code: routerText(commandRow.command_code),
      topic_type: routerText(commandRow.topic_type),
      idempotency_key: idempotencyKey,
      worker_workflow: routerText(commandRow.worker_workflow),
    },
  };
  return {
    decision: {
      kind: 'ROUTE',
      route: {
        command_code: routerText(commandRow.command_code),
        topic_type: routerText(commandRow.topic_type),
        worker_workflow: routerText(commandRow.worker_workflow),
        branch_id: routerText(topic?.branch_id),
        permission_code: routerText(commandRow.permission_code) || null,
        operation_id: routerText(normalized?.envelope?.operation_id),
        idempotency_key: idempotencyKey,
        worker_target: workerTarget.workflow_name,
        envelope: workerEnvelope,
      },
      reservation: dispatchReservation,
      write_plan: [],
    },
    text: routerText(messages.get('ROUTER_COMMAND_ACCEPTED')),
  };
}


